// Server component (default) — no directive
async function Page({ id }) {
  const product = await db.products.find(id);
  return <AddToCart productId={product.id} />; // client island
}

'use client';
import { useState } from 'react';
export function LikeButton({ initial }) {
  const [likes, setLikes] = useState(initial);
  return <button onClick={() => setLikes(l => l + 1)}>{likes}</button>;
}

async function Reviews({ productId }) {
  const reviews = await db.reviews.forProduct(productId);
  return <ul>{reviews.map(r => <li key={r.id}>{r.text}</li>)}</ul>;
}

// OK: serializable
<LikeButton initial={3} title={"Hello"} />
// NOT OK: function is not serializable across the boundary
<LikeButton onLike={() => save()} />

'use server';
export async function addToCart(productId) {
  const user = await auth(); // validate on the server
  await db.cart.add(user.id, productId);
}

