// Server component (default): no 'use client', can be async, fetches directly.

async function ProductPage({ id }) {
  // Direct data access on the server — no client fetch, ships no JS for this code.
  const product = await db.products.findById(id);
  return (
    <article>
      <h1>{product.name}</h1>
      <p>{product.description}</p>
      <p>${product.price}</p>
      {/* Interactive island is a client component, imported below */}
      <AddToCart productId={product.id} />
    </article>
  );
}

