// ILLUSTRATIVE ONLY — shows a client component's shape.
'use client';

// A client component: ships to the browser, can use state and handlers.
function AddToCart({ productId }) {
  const [added, setAdded] = useState(false);
  return (
    <button onClick={() => setAdded(true)}>
      {added ? 'Added!' : `Add ${productId} to cart`}
    </button>
  );
}

// Runnable wrapper so the sandbox shows the interactive part working.
function App() {
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <p>Client component (the interactive island):</p>
      <AddToCart productId="sku-42" />
    </div>
  );
}

