// ILLUSTRATIVE fix — two responsibilities, two components.
//
// Server component (default): fetches and composes only.
//   async function ProfileCard({ userId }) {
//     const user = await db.users.findById(userId);
//     return <ProfileBody name={user.name} bio={user.bio} />; // serializable props
//   }
//
// Client component: owns the interactivity.
'use client';
function ProfileBody({ name, bio }) {
  const [open, setOpen] = useState(false);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>{name}</h2>
      <button onClick={() => setOpen(o => !o)}>Toggle</button>
      {open && <p>{bio}</p>}
    </div>
  );
}

function App() {
  return <ProfileBody name="Ada" bio="Built the first algorithm." />;
}

